const D = { scale:1, energy:.6, bights:7, leads:3, speed:1, density:.55, hue:32, x:.5, y:.5, style:'manila', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width,height), cx=width*P.x, cy=height*P.y, t=K.t, sty=P.style;
const hsh = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const B = Math.max(3, Math.min(13, Math.round(P.bights)));
const Lp = Math.max(2, Math.min(7, Math.round(P.leads)));
const N = Math.max(420, Math.min(720, Math.round(440 + P.density*260)));
const R = 0.29*u*P.scale, a = 0.12*u*P.scale;
const rw = (0.028 + 0.022*P.energy)*u*P.scale;
const rot = t*(0.06 + P.speed*0.05);
const flow = t*(0.9 + P.speed*1.4);
const glint = 0.5 + 0.42*Math.sin(t*0.23) + 0.1*Math.sin(t*0.47+1.7); // symmetry-breaking sweep
const bass = Math.min(0.5, A.bass*0.6);

if (sty==='ink') background(36,10,58); else background(28,45,8);

// cord palette
function cordCol(bandV, hu){
  if (sty==='ink') return [34, 12, 88-bandV*30];
  if (sty==='gilt') return [46, 62, 30+bandV*55+10*bass];
  if (sty==='candy') return [hu, 78, 30+bandV*55];
  if (sty==='neon') return [hu, 85, 20+bandV*60];
  return [(P.hue-6)%360, 46, 22+bandV*46+8*bass]; // manila
}

const pts=[];
for (let i=0;i<=N;i++){
  const th = i/N*Math.PI*2;
  const rad = R + a*Math.cos(B*th);
  const ang = Lp*th + rot;
  pts.push({x:cx+rad*Math.cos(ang), y:cy+rad*Math.sin(ang), z:Math.sin(B*th), th, i});
}
const segs=[];
for (let i=0;i<N;i++){ const p1=pts[i],p2=pts[i+1]; segs.push({p1,p2, z:(p1.z+p2.z)*0.5, i}); }
segs.sort((m,n)=>m.z-n.z);
strokeCap(ROUND); strokeJoin(ROUND); noFill();
const near = segs.length*0.78;

for (let k=0;k<segs.length;k++){
  const sg=segs[k], lit=Math.max(0,Math.min(1,(sg.z+1)*0.5));
  const sw = Math.max(0, 1 - Math.abs((sg.p1.x/width) - glint)*2.4); // glint sweep
  const hu = (P.hue + sg.i/N*260)%360;
  if (sty==='neon'){
    blendMode(ADD);
    const cc=cordCol(lit,hu); stroke(cc[0],cc[1],cc[2]*0.55, 30*(P.alpha/100)); strokeWeight(rw*1.6);
    line(sg.p1.x,sg.p1.y,sg.p2.x,sg.p2.y);
    stroke(cc[0],45,90, 80*(P.alpha/100)); strokeWeight(rw*0.4);
    line(sg.p1.x,sg.p1.y,sg.p2.x,sg.p2.y);
    blendMode(BLEND);
    continue;
  }
  if (k>near){ drawingContext.shadowBlur=rw*0.8; drawingContext.shadowColor='rgba(0,0,0,0.5)'; }
  const cc=cordCol(lit*0.5, hu);
  stroke(cc[0], cc[1]+6, cc[2]*0.5, P.alpha); strokeWeight(rw*1.15); // casing
  line(sg.p1.x,sg.p1.y,sg.p2.x,sg.p2.y);
  drawingContext.shadowBlur=0;
  const cb=cordCol(0.6+0.5*sw, hu);
  stroke(cb[0], cb[1], Math.min(100, cb[2]+18*sw), P.alpha); strokeWeight(rw*0.7); // body
  line(sg.p1.x,sg.p1.y,sg.p2.x,sg.p2.y);
  // barber-pole twist stripe travelling along the cord length
  const stripe = Math.sin(sg.i*0.9 - flow);
  if (stripe > 0.55){
    stroke((cc[0]+8)%360, Math.max(0,cc[1]-30), Math.min(100, 78+16*sw), P.alpha*0.85); strokeWeight(rw*0.22);
    line(sg.p1.x,sg.p1.y,sg.p2.x,sg.p2.y);
  }
}
drawingContext.shadowBlur=0;
blendMode(BLEND);
